import{_ as a,a0 as l,w as u,s as r,I as i,x as n,a1 as e,A as o,ao as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"Linux 初学者：如何在 Ubuntu 中重启网络 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 初学者：如何在 Ubuntu 中重启网络 | LCTT (201905) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 初学者：如何在 Ubuntu 中重启网络 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 初学者：如何在 Ubuntu 中重启网络 | LCTT (201905) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201905/20190307 How to Restart a Network in Ubuntu -Beginner-s Tip","title":"Linux 初学者：如何在 Ubuntu 中重启网络","tag":"201905","desc":""},"relativePath":"201905/20190307 How to Restart a Network in Ubuntu -Beginner-s Tip.md","filePath":"[post].md"}'),d={name:"201905/20190307 How to Restart a Network in Ubuntu -Beginner-s Tip.md"};function m(g,t,f,c,h,b){const s=l("Link");return u(),r("div",null,[t[29]||(t[29]=i("h1",{id:"linux-初学者-如何在-ubuntu-中重启网络",tabindex:"-1"},[n("Linux 初学者：如何在 Ubuntu 中重启网络 "),i("a",{class:"header-anchor",href:"#linux-初学者-如何在-ubuntu-中重启网络","aria-label":"Permalink to “Linux 初学者：如何在 Ubuntu 中重启网络”"},"​")],-1)),i("p",null,[t[1]||(t[1]=n("你",-1)),e(s,{href:"https://itsfoss.com/fix-no-wireless-network-ubuntu/"},{default:o(()=>[...t[0]||(t[0]=[n("是否正在使用基于 Ubuntu 的系统，然后发现无法连接网络",-1)])]),_:1}),t[2]||(t[2]=n("？你一定会很惊讶，很多的问题都可以简单地通过重启服务解决。",-1))]),t[30]||(t[30]=i("p",null,"在这篇文章中，我会介绍在 Ubuntu 或者其他 Linux 发行版中重启网络的几种方法，你可以根据自身需要选择对应的方法。这些方法基本分为两类：",-1)),t[31]||(t[31]=i("p",null,[i("img",{src:"https://i1.wp.com/itsfoss.com/wp-content/uploads/2019/03/ubuntu-restart-network.png?resize=800%2C450&ssl=1",alt:"Ubuntu Restart Network"})],-1)),t[32]||(t[32]=i("h3",{id:"通过命令行方式重启网络",tabindex:"-1"},[n("通过命令行方式重启网络 "),i("a",{class:"header-anchor",href:"#通过命令行方式重启网络","aria-label":"Permalink to “通过命令行方式重启网络”"},"​")],-1)),i("p",null,[t[4]||(t[4]=n("如果你使用的 Ubuntu 服务器版，那么你已经在使用命令行终端了。如果你使用的是桌面版，那么你可以通过快捷键 ",-1)),t[5]||(t[5]=i("code",null,"Ctrl+Alt+T",-1)),t[6]||(t[6]=n()),e(s,{href:"https://itsfoss.com/ubuntu-shortcuts/"},{default:o(()=>[...t[3]||(t[3]=[n("Ubuntu 键盘快捷键",-1)])]),_:1}),t[7]||(t[7]=n(" 打开命令行终端。",-1))]),t[33]||(t[33]=p('<p>在 Ubuntu 中，有多个命令可以重启网络。这些命令，一部分或者说大部分，也适用于在 Debian 或者其他的 Linux 发行版中重启网络。</p><h4 id="_1、network-manager-服务" tabindex="-1">1、network manager 服务 <a class="header-anchor" href="#_1、network-manager-服务" aria-label="Permalink to “1、network manager 服务”">​</a></h4><p>这是通过命令行方式重启网络最简单的方法。它相当于是通过图形化界面重启网络（重启 Network-Manager 服务）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo service network-manager restart</span></span></code></pre></div><p>此时，网络图标会消失一会儿然后重新显示。</p><h4 id="_2、systemd" tabindex="-1">2、systemd <a class="header-anchor" href="#_2、systemd" aria-label="Permalink to “2、systemd”">​</a></h4><p><code>service</code> 命令仅仅是这个方式的一个封装（同样的也是 init.d 系列脚本和 Upstart 相关命令的封装）。<code>systemctl</code> 命令的功能远多于 <code>service</code> 命令。通常我更喜欢使用这个命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo systemctl restart NetworkManager.service</span></span></code></pre></div><p>这时，网络图标又会消失一会儿。 如果你想了解 <code>systemctl</code> 的其他选项, 可以参考 man 帮助文档。</p><h4 id="_3、nmcli" tabindex="-1">3、nmcli <a class="header-anchor" href="#_3、nmcli" aria-label="Permalink to “3、nmcli”">​</a></h4><p>这是 Linux 上可以管理网络的另一个工具。这是一个功能强大而且实用的工具。很多系统管理员都喜欢使用该工具，因为它非常容易使用。</p><p>这种方法有两个操作步骤：关闭网络，再开启网络。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo nmcli networking off</span></span></code></pre></div><p>这样就会关闭网络，网络图标会消失。接下来，再开启网络：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo nmcli networking on</span></span></code></pre></div><p>你可以通过 man 帮助文档了解 nmcli 的更多用法。</p><h4 id="_4、ifup-ifdown" tabindex="-1">4、ifup &amp; ifdown <a class="header-anchor" href="#_4、ifup-ifdown" aria-label="Permalink to “4、ifup &amp; ifdown”">​</a></h4>',17)),i("p",null,[t[9]||(t[9]=n("这两个命令直接操作网口，切换网口是否可以收发包的状态。这是 ",-1)),e(s,{href:"https://itsfoss.com/basic-linux-networking-commands/"},{default:o(()=>[...t[8]||(t[8]=[n("Linux 中最应该了解的网络命令",-1)])]),_:1}),t[10]||(t[10]=n(" 之一。",-1))]),t[34]||(t[34]=p('<p>使用 <code>ifdown</code> 关闭所有网口，再使用 <code>ifup</code> 重新启用网口。</p><p>通常推荐的做法是将这两个命令一起使用。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo ifdown -a &amp;&amp; sudo ifup -a</span></span></code></pre></div><p>注意：这种方法不会让网络图标从系统托盘中消失，另外，各种网络连接也会断。</p><h4 id="补充工具-nmtui" tabindex="-1">补充工具： nmtui <a class="header-anchor" href="#补充工具-nmtui" aria-label="Permalink to “补充工具： nmtui”">​</a></h4><p>这是系统管理员们常用的另外一种方法。它是在命令行终端中管理网络的文本菜单工具。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>nmtui</span></span></code></pre></div><p>打开如下菜单：</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2019/03/nmtui_menu.png?fit=800%2C602&amp;ssl=1" alt="nmtui Menu"></p><p>注意：在 nmtui 中，可以通过 <code>up</code> 和 <code>down</code> 方向键选择选项。</p><p>选择 “Activate a connection”：</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2019/03/nmtui_menu_select_option.png?fit=800%2C579&amp;ssl=1" alt="nmtui Menu Select &quot;Activate a connection&quot;"></p><p>按下回车键，打开 “connections” 菜单。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2019/03/nmui_connection_menu_on.png?fit=800%2C585&amp;ssl=1" alt="nmtui Connections Menu"></p><p>接下来，选择前面带星号（*）的网络。在这个例子中，就是 MGEO72。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2019/03/nmui_select_connection_on.png?fit=800%2C576&amp;ssl=1" alt="Select your connection in the nmtui connections menu."></p><p>按下回车键。 这就将“停用”你的网络连接。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2019/03/nmui_connection_menu_off.png?fit=800%2C572&amp;ssl=1" alt="nmtui Connections Menu with no active connection"></p><p>选择你要连接的网络：</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2019/03/nmui_select_connection_off.png?fit=800%2C566&amp;ssl=1" alt="Select the connection you want in the nmtui connections menu."></p><p>按下回车键。这样就重新激活了所选择的网络连接。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2019/03/nmui_connection_menu_on-1.png?fit=800%2C585&amp;ssl=1" alt="nmtui Connections Menu"></p><p>按下 <code>Tab</code> 键两次，选择 “Back”：</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2019/03/nmui_connection_menu_back.png?fit=800%2C585&amp;ssl=1" alt="Select &quot;Back&quot; in the nmtui connections menu."></p><p>按下回车键，回到 nmtui 的主菜单。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2019/03/nmtui_menu_select_option-1.png?fit=800%2C579&amp;ssl=1" alt="nmtui Main Menu"></p><p>选择 “Quit” ：</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2019/03/nmui_menu_quit.png?fit=800%2C580&amp;ssl=1" alt="nmtui Quit Main Menu"></p><p>退出该界面，返回到命令行终端。</p><p>就这样，你已经成功重启网络了。</p><h3 id="通过图形化界面重启网络" tabindex="-1">通过图形化界面重启网络 <a class="header-anchor" href="#通过图形化界面重启网络" aria-label="Permalink to “通过图形化界面重启网络”">​</a></h3><p>显然，这是 Ubuntu 桌面版用户重启网络最简单的方法。如果这个方法不生效，你可以尝试使用前文提到的命令行方式重启网络。</p>',32)),i("p",null,[t[12]||(t[12]=n("NM 小程序是 ",-1)),e(s,{href:"https://wiki.gnome.org/Projects/NetworkManager"},{default:o(()=>[...t[11]||(t[11]=[n("NetworkManager",-1)])]),_:1}),t[13]||(t[13]=n(" 的系统托盘程序标志。我们将使用它来重启网络。",-1))]),t[35]||(t[35]=p('<p>首先，查看顶部状态栏。你会在系统托盘找到一个网络图标 （因为我使用 Wi-Fi，所以这里是一个 Wi-Fi 图标）。</p><p>接下来，点击该图标（也可以点击音量图标或电池图标）。打开菜单。选择 “Turn Off” 关闭网络。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2019/03/restart-network-ubuntu-1.jpg?resize=800%2C400&amp;ssl=1" alt="Restart network in Ubuntu"></p><p>网络图标会在状态栏中消失，这表示你已经成功关闭网络了。</p><p>再次点击系统托盘重新打开菜单，选择 “Turn On”，重新开启网络。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2019/03/restart-network-ubuntu-2.jpg?resize=800%2C400&amp;ssl=1" alt="Restarting network in Ubuntu"></p><p>恭喜！你现在已经重启你的网络了。</p><h4 id="其他提示-刷新可用网络列表" tabindex="-1">其他提示：刷新可用网络列表 <a class="header-anchor" href="#其他提示-刷新可用网络列表" aria-label="Permalink to “其他提示：刷新可用网络列表”">​</a></h4><p>如果你已经连接上一个网络，但是你想连接到另外一个网络，你如何刷新 WiFi 列表，查找其他可用的网络呢？我来向你展示一下。</p><p>Ubuntu 没有可以直接 “刷新 WiFi 网络” 的选项，它有点隐蔽。</p><p>你需要再次打开配置菜单，然后点击 “Select Network” 。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2019/03/select-wifi-network-ubuntu.jpg?resize=800%2C400&amp;ssl=1" alt="Refresh wifi network list in Ubuntu"></p><p>选择对应的网络修改你的 WiFi 连接。</p><p>你无法马上看到可用的无线网络列表。打开网络列表之后，大概需要 5 秒才会显示其它可用的无线网络。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2019/03/select-wifi-network-ubuntu-1.jpg?resize=800%2C400&amp;ssl=1" alt="Select another wifi network in Ubuntu"></p><p>等待大概 5 秒钟，看到其他可用的网络。</p><p>现在，你就可以选择你想要连接的网络，点击连接。这样就完成了。</p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>重启网络连接是每个 Linux 用户在使用过程中必须经历的事情。</p><p>我们希望这些方法可以帮助你处理这样的问题！</p><p>你是如何重启或管理你的网络的？我们是否还有遗漏的？请在下方留言。</p><hr>',22)),i("p",null,[t[15]||(t[15]=n("via: ",-1)),e(s,{href:"https://itsfoss.com/restart-network-ubuntu"},{default:o(()=>[...t[14]||(t[14]=[n("https://itsfoss.com/restart-network-ubuntu",-1)])]),_:1})]),i("p",null,[t[20]||(t[20]=n("作者：",-1)),e(s,{href:"https://itsfoss.com/author/sergiu/"},{default:o(()=>[...t[16]||(t[16]=[n("Sergiu",-1)])]),_:1}),t[21]||(t[21]=n(" 选题：",-1)),e(s,{href:"https://github.com/lujun9972"},{default:o(()=>[...t[17]||(t[17]=[n("lujun9972",-1)])]),_:1}),t[22]||(t[22]=n(" 译者：",-1)),e(s,{href:"https://github.com/bodhix"},{default:o(()=>[...t[18]||(t[18]=[n("bodhix",-1)])]),_:1}),t[23]||(t[23]=n(" 校对：",-1)),e(s,{href:"https://github.com/wxy"},{default:o(()=>[...t[19]||(t[19]=[n("wxy",-1)])]),_:1})]),i("p",null,[t[26]||(t[26]=n("本文由 ",-1)),e(s,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[24]||(t[24]=[n("LCTT",-1)])]),_:1}),t[27]||(t[27]=n(" 原创编译，",-1)),e(s,{href:"https://linux.cn/"},{default:o(()=>[...t[25]||(t[25]=[n("Linux中国",-1)])]),_:1}),t[28]||(t[28]=n(" 荣誉推出",-1))])])}const x=a(d,[["render",m]]);export{C as __pageData,x as default};
